/* ------------------------- point-soup shape kit -------------------------- */
function sph(out,cx,cy,cz,r,n,cr,cg,cb,vary){
  for (let i=0;i<n;i++){
    const u = SITE()*2-1, ph = SITE()*TAU, s = Math.sqrt(1-u*u);
    const rad = r*(0.86+0.14*SITE());
    const k = 1 + (SITE()*2-1)*vary;
    out.push(cx+Math.cos(ph)*s*rad, cy+u*rad, cz+Math.sin(ph)*s*rad, cr*k, cg*k, cb*k);
  }
}
function taper(out,x0,y0,z0,x1,y1,z1,r0,r1,n,cr,cg,cb,vary){
  for (let i=0;i<n;i++){
    const t = SITE(), a = SITE()*TAU, rad = lerp(r0,r1,t)*(0.75+0.5*SITE());
    const k = 1 + (SITE()*2-1)*vary;
    out.push(lerp(x0,x1,t)+Math.cos(a)*rad, lerp(y0,y1,t), lerp(z0,z1,t)+Math.sin(a)*rad,
             cr*k, cg*k, cb*k);
  }
}
function box(out,cx,cy,cz,hx,hy,hz,yaw,step,cr,cg,cb,vary){
  const cs = Math.cos(yaw), sn = Math.sin(yaw);
  const fx = Math.max(2,Math.round(hx*2/step)), fy = Math.max(2,Math.round(hy*2/step)), fz = Math.max(2,Math.round(hz*2/step));
  const put = (x,y,z)=>{
    const k = 1 + (SITE()*2-1)*vary;
    out.push(cx + x*cs + z*sn, cy + y, cz - x*sn + z*cs, cr*k, cg*k, cb*k);
  };
  for (let i=0;i<=fx;i++) for (let k=0;k<=fy;k++){
    const x = -hx + 2*hx*i/fx, y = -hy + 2*hy*k/fy;
    if (SITE()<0.75){ put(x,y, hz); put(x,y,-hz); }
  }
  for (let i=0;i<=fx;i++) for (let k=0;k<=fz;k++){
    const x = -hx + 2*hx*i/fx, z = -hz + 2*hz*k/fz;
    if (SITE()<0.85){ put(x, hy, z); put(x,-hy,z); }
  }
  for (let i=0;i<=fz;i++) for (let k=0;k<=fy;k++){
    const z = -hz + 2*hz*i/fz, y = -hy + 2*hy*k/fy;
    if (SITE()<0.35){ put(hx,y,z); put(-hx,y,z); }
  }
}
function cyl(out,cx,cy,cz,r0,r1,h,n,cr,cg,cb,vary){
  for (let i=0;i<n;i++){
    const t = SITE(), a = SITE()*TAU, rad = lerp(r0,r1,t);
    const k = 1 + (SITE()*2-1)*vary;
    out.push(cx+Math.cos(a)*rad, cy + h*t, cz+Math.sin(a)*rad, cr*k, cg*k, cb*k);
  }
}

/* ------------------------------- the forest ------------------------------ */
const BARK = [0.185,0.140,0.115];
const trees = [];
function buildTree(px,pz,scale){
  const pts = [];
  const gy = hAt(px,pz);
  const H  = rr(5.2,7.6)*scale;
  const lean = rr(-0.10,0.10), leanZ = rr(-0.10,0.10);
  const topX = px + lean*H, topZ = pz + leanZ*H, topY = gy + H;
  // trunk
  const tn = Math.round(150*scale);
  for (let i=0;i<tn;i++){
    const t = SITE();
    const r = lerp(0.30,0.10,t)*scale*(0.75+0.5*SITE());
    const a = SITE()*TAU;
    const tx = px + lean*H*t, tz = pz + leanZ*H*t, ty = gy + H*t;
    const k = 0.75+0.45*t;
    pts.push(tx+Math.cos(a)*r, ty, tz+Math.sin(a)*r, BARK[0]*k, BARK[1]*k, BARK[2]*k);
  }
  // limbs
  const limbs = ri(3,5);
  const limbTips = [];
  for (let L=0;L<limbs;L++){
    const ang = L/limbs*TAU + rr(-0.5,0.5);
    const t0 = rr(0.55,0.78);
    const len = rr(1.5,3.0)*scale;
    const x0 = px + lean*H*t0, z0 = pz + leanZ*H*t0, y0 = gy + H*t0;
    const x1 = x0 + Math.cos(ang)*len, z1 = z0 + Math.sin(ang)*len, y1 = y0 + rr(0.6,1.8)*scale;
    limbTips.push([x1,y1,z1]);
    const n = Math.round(46*scale);
    for (let i=0;i<n;i++){
      const t = SITE(), a = SITE()*TAU, rad = lerp(0.13,0.05,t)*scale*(0.6+0.8*SITE());
      pts.push(lerp(x0,x1,t)+Math.cos(a)*rad, lerp(y0,y1,t), lerp(z0,z1,t)+Math.sin(a)*rad,
               0.20,0.155,0.13);
    }
  }
  // blossom canopy — a few overlapping puffs
  const puffs = [];
  const cxn = px + lean*H, czn = pz + leanZ*H, cyn = gy + H;
  puffs.push([cxn, cyn+0.35*scale, czn, rr(2.3,3.0)*scale, rr(1.35,1.75)*scale, rr(2.3,3.0)*scale]);
  for (const lt of limbTips) puffs.push([lt[0], lt[1]+0.55*scale, lt[2], rr(1.25,1.9)*scale, rr(0.9,1.25)*scale, rr(1.25,1.9)*scale]);
  puffs.push([cxn, cyn+1.6*scale, czn, rr(1.4,2.0)*scale, rr(0.9,1.2)*scale, rr(1.4,2.0)*scale]);
  const petalN = Math.round(1250*scale*scale);
  const per = Math.max(1, Math.round(petalN/puffs.length));
  for (const pf of puffs){
    for (let i=0;i<per;i++){
      const u = SITE()*2-1, ph = SITE()*TAU, s = Math.sqrt(1-u*u);
      const rad = Math.pow(SITE(), 0.34);
      const x = pf[0] + Math.cos(ph)*s*pf[3]*rad;
      const y = pf[1] + u*pf[4]*rad;
      const z = pf[2] + Math.sin(ph)*s*pf[5]*rad;
      // lacy gaps so canopies read as blossom clusters, not blobs
      if (fbm(x*0.85+3.3, z*0.85-1.7, 2) * 0.6 + fbm(y*0.9+8.1, x*0.9+2.2, 2) * 0.4 < 0.30) continue;
      if (SITE() < 0.20) continue;
      const inner = 1 - clamp(rad,0,1);
      const shade = 0.55 + 0.45*inner;            // darker inside the cluster
      const warm  = SITE();
      const cr = lerp(0.86, 1.00, warm), cg = lerp(0.50, 0.68, warm), cb = lerp(0.62, 0.78, warm);
      const sway = clamp((y-gy)/H, 0, 1.25);
      pts.push(x, y, z, cr*shade, cg*shade, cb*shade, sway);
    }
  }
  // fill the 7th slot for the trunk/limb points (no sway)
  for (let i=0;i<pts.length;i+=7){
    if (pts[i+6] === undefined) pts[i+6] = 0;
    else if (i>0 && pts[i+6] === undefined) pts[i+6] = 0;
  }
  // trunk & limb points were pushed with 6 values — rebuild the array consistently
  const fixed = [];
  let q = 0;
  while (q < pts.length){
    if (q % 7 === 0 && q+6 < pts.length && typeof pts[q+6] === 'number'){ fixed.push(pts[q],pts[q+1],pts[q+2],pts[q+3],pts[q+4],pts[q+5],pts[q+6]); q += 7; }
    else { fixed.push(pts[q],pts[q+1],pts[q+2],pts[q+3],pts[q+4],pts[q+5],0); q += 6; }
  }
  return { x:px, z:pz, y:gy, phase: SITE()*TAU, pts: new Float32Array(fixed) };
}
function buildForest(){
  const placed = [];
  let tries = 0;
  while (placed.length < 44 && tries < 4000){
    tries++;
    const a = SITE()*TAU, d = 7 + 88*Math.pow(SITE(), 0.72);
    const x = Math.cos(a)*d, z = Math.sin(a)*d;
    const y = hAt(x,z);
    if (y < 0.9) continue;                                   // keep the pond clear
    if (Math.hypot(x+16.8, z-15.5) < 6) continue;            // keep the torii clear
    let ok = true;
    for (const p of placed) if (Math.hypot(p[0]-x,p[1]-z) < 6.5) { ok = false; break; }
    if (!ok) continue;
    placed.push([x,z]);
    trees.push(buildTree(x, z, 0.75 + 0.55*SITE() + d*0.006));
  }
}

/* --------------------- torii gate, stone lanterns, path ------------------ */
const statics = [];      // {x,y,z,r,g,b}
const glows   = [];      // {x,y,z,r,g,b,rad,str}
function buildShrine(){
  const TX = -16.8, TZ = 15.5;
  let fx = TX, fz = TZ;
  const fl = Math.hypot(fx,fz); fx/=fl; fz/=fl;
  const pxx = fz, pzz = -fx;                       // pillar spread axis
  const yaw = Math.atan2(pxx,pzz);
  const VERM = [0.62,0.155,0.17];
  const gy = Math.max(hAt(TX,TZ), WATER-0.6);
  const H = 6.4, half = 2.7, thick = 0.42;
  for (const s of [-1,1]){
    const bx = TX + pxx*half*s, bz = TZ + pzz*half*s;
    const by = Math.max(hAt(bx,bz), WATER-0.8);
    box(statics, bx, by + (H+gy-by)*0.5, bz, thick, (H+gy-by)*0.5, thick, yaw, 0.30, VERM[0],VERM[1],VERM[2], 0.10);
  }
  box(statics, TX, gy+H+0.5, TZ, half+1.5, 0.30, 0.34, yaw, 0.34, VERM[0]*1.08,VERM[1]*1.05,VERM[2]*1.05, 0.08); // kasagi
  box(statics, TX, gy+H+0.12, TZ, half+0.35, 0.16, 0.22, yaw, 0.30, VERM[0]*0.85,VERM[1]*0.85,VERM[2]*0.85, 0.08);
  box(statics, TX, gy+H*0.78, TZ, half+0.15, 0.20, 0.20, yaw, 0.34, VERM[0]*0.92,VERM[1]*0.92,VERM[2]*0.92, 0.08); // nuki
  // paper lanterns hanging under the kasagi
  for (const s of [-1,1]){
    const lx = TX + pxx*(half*0.72)*s, lz = TZ + pzz*(half*0.72)*s;
    const ly = gy + H*0.78 - 0.75;
    taper(statics, lx, ly+0.32, lz, lx, ly-0.42, lz, 0.10, 0.62, 90, 0.98,0.84,0.62, 0.10);
    cyl(statics, lx, ly+0.40, lz, 0.02, 0.02, 0.30, 12, 0.20,0.18,0.16, 0.05);
    glows.push({x:lx,y:ly,z:lz,r:1.0,g:0.70,b:0.34,rad:2.2,str:0.55});
  }
  // stone lanterns along a mossy path
  const stone = [0.30,0.30,0.32];
  const pathPts = [[-3.0,-1.5],[-7.5,3.0],[-11.5,8.0],[-14.0,12.4],[-16.0,13.6]];
  for (const [lx,lz] of pathPts){
    const ly = hAt(lx,lz);
    if (ly < 0.15) continue;
    cyl(statics, lx, ly-0.05, lz, 0.62, 0.50, 0.42, 110, stone[0]*0.6,stone[1]*0.6,stone[2]*0.6, 0.10);
    cyl(statics, lx, ly+0.36, lz, 0.19, 0.17, 1.05, 90, stone[0]*0.8,stone[1]*0.8,stone[2]*0.8, 0.08);
    cyl(statics, lx, ly+1.40, lz, 0.50, 0.44, 0.20, 90, stone[0]*0.9,stone[1]*0.9,stone[2]*0.9, 0.08);
    cyl(statics, lx, ly+1.58, lz, 0.40, 0.34, 0.50, 110, 0.42,0.37,0.28, 0.12);   // fire box
    taper(statics, lx, ly+2.42, lz, lx, ly+2.05, lz, 0.72, 0.42, 110, stone[0],stone[1],stone[2], 0.08);
    cyl(statics, lx, ly+2.36, lz, 0.10, 0.06, 0.22, 24, stone[0],stone[1],stone[2], 0.06);
    glows.push({x:lx,y:ly+1.82,z:lz,r:1.0,g:0.66,b:0.30,rad:1.7,str:0.48});
  }
}

/* ----------------------------- sky contents ------------------------------ */
const stars = [];
function buildStars(){
  for (let i=0;i<1500;i++){
    const u = SITE()*2-1, ph = SITE()*TAU, s = Math.sqrt(Math.max(0,1-u*u));
    const x = Math.cos(ph)*s, y = u, z = Math.sin(ph)*s;
    if (y < 0.015) continue;
    const d = x*MOONX + y*MOONY + z*MOONZ;
    const b = (0.25 + 0.75*Math.pow(SITE(),2.2)) * smoothstep(0.02,0.28,y) * smoothstep(0.995,0.955,d);
    if (b < 0.02) continue;
    const t = SITE();
    stars.push({x,y,z,b,ph:SITE()*TAU,sp:0.7+SITE()*2.2,
      r:lerp(0.72,1.0,t), g:lerp(0.80,0.97,t), bl:lerp(1.0,0.86,t)});
  }
}
const petals = [], flies = [];
function buildWeather(){
  for (let i=0;i<340;i++) petals.push(newPetal(true));
  for (let i=0;i<90;i++){
    const a = SITE()*TAU, d = 6 + 46*SITE();
    const x = LAKE_X*0.55 + Math.cos(a)*d*0.8, z = LAKE_Z*0.55 + Math.sin(a)*d*0.8;
    flies.push({x, y:hAt(x,z)+rr(0.4,2.4), z, ph:SITE()*TAU, sp:rr(0.25,0.8), r:rr(1.2,3.0), b:0, c:SITE()});
  }
}
function newPetal(init){
  return {
    x: playerX + rr(-34,34), z: playerZ + rr(-34,34),
    y: (init ? rr(0.5,17) : rr(9,17)),
    sp: rr(0.35,1.05), ph: SITE()*TAU, sw: rr(0.35,1.15), sz: rr(0.6,1.5),
    tone: SITE(), size: SITE()<0.3?1:0
  };
}

//__NEXT__

