+    const rad = r*(0.86+0.14*SITE());
+    const k = 1 + (SITE()*2-1)*vary;
+    out.push(cx+Math.cos(ph)*s*rad, cy+u*rad, cz+Math.sin(ph)*s*rad, cr*k, cg*k, cb*k);
+  }
+}
+function taper(out,x0,y0,z0,x1,y1,z1,r0,r1,n,cr,cg,cb,vary){
+  for (let i=0;i<n;i++){
+    const t = SITE(), a = SITE()*TAU, rad = lerp(r0,r1,t)*(0.75+0.5*SITE());
+    const k = 1 + (SITE()*2-1)*vary;
+    out.push(lerp(x0,x1,t)+Math.cos(a)*rad, lerp(y0,y1,t), lerp(z0,z1,t)+Math.sin(a)*rad,
+             cr*k, cg*k, cb*k);
+  }
+}
+function box(out,cx,cy,cz,hx,hy,hz,yaw,step,cr,cg,cb,vary){
+  const cs = Math.cos(yaw), sn = Math.sin(yaw);
+  const fx = Math.max(2,Math.round(hx*2/step)), fy = Math.max(2,Math.round(hy*2/step)), fz = Math.max(2,Math.round(hz*2/step));
+  const put = (x,y,z)=>{
+    const k = 1 + (SITE()*2-1)*vary;
+    out.push(cx + x*cs + z*sn, cy + y, cz - x*sn + z*cs, cr*k, cg*k, cb*k);
+  };
+  for (let i=0;i<=fx;i++) for (let k=0;k<=fy;k++){
+    const x = -hx + 2*hx*i/fx, y = -hy + 2*hy*k/fy;
+    if (SITE()<0.75){ put(x,y, hz); put(x,y,-hz); }
+  }
+  for (let i=0;i<=fx;i++) for (let k=0;k<=fz;k++){
+    const x = -hx + 2*hx*i/fx, z = -hz + 2*hz*k/fz;
+    if (SITE()<0.85){ put(x, hy, z); put(x,-hy,z); }
+  }
+  for (let i=0;i<=fz;i++) for (let k=0;k<=fy;k++){
+    const z = -hz + 2*hz*i/fz, y = -hy + 2*hy*k/fy;
+    if (SITE()<0.35){ put(hx,y,z); put(-hx,y,z); }
+  }
+}
+function cyl(out,cx,cy,cz,r0,r1,h,n,cr,cg,cb,vary){
+  for (let i=0;i<n;i++){
+    const t = SITE(), a = SITE()*TAU, rad = lerp(r0,r1,t);
+    const k = 1 + (SITE()*2-1)*vary;
+    out.push(cx+Math.cos(a)*rad, cy + h*t, cz+Math.sin(a)*rad, cr*k, cg*k, cb*k);
+  }
+}
+
+/* ------------------------------- the forest ------------------------------ */
+const BARK = [0.185,0.140,0.115];
+const trees = [];
+function buildTree(px,pz,scale){
+  const pts = [];
+  const gy = hAt(px,pz);
+  const H  = rr(5.2,7.6)*scale;
