+    const t = SITE();
+    stars.push({x,y,z,b,ph:SITE()*TAU,sp:0.7+SITE()*2.2,
+      r:lerp(0.72,1.0,t), g:lerp(0.80,0.97,t), bl:lerp(1.0,0.86,t)});
+  }
+}
+const petals = [], flies = [];
+function buildWeather(){
+  for (let i=0;i<340;i++) petals.push(newPetal(true));
+  for (let i=0;i<90;i++){
+    const a = SITE()*TAU, d = 6 + 46*SITE();
+    const x = LAKE_X*0.55 + Math.cos(a)*d*0.8, z = LAKE_Z*0.55 + Math.sin(a)*d*0.8;
