+    y: (init ? rr(0.5,17) : rr(9,17)),
+    sp: rr(0.35,1.05), ph: SITE()*TAU, sw: rr(0.35,1.15), sz: rr(0.6,1.5),
+    tone: SITE(), size: SITE()<0.3?1:0
