let projX = 1, projY = 1, cxc = 0, cyc = 0, tanH = 0.8, tanV = 0.55;
let bgR = 0, bgG = 0, bgB = 0;
const FOV_H = 1.36;

const PRESETS = [ {name:'low',cw:11}, {name:'medium',cw:8}, {name:'high',cw:6} ];
let preset = 2;
const MAXCELLS = 27000;

function buildGlyphs(){
  const S = 4, w = cellW*S, h = cellH*S;
  const cc = document.createElement('canvas'); cc.width = w; cc.height = h;
  const g = cc.getContext('2d', { willReadFrequently:true });
  glyphs = [];
  for (let i=0;i<RAMP.length;i++){
    g.clearRect(0,0,w,h);
    g.fillStyle = '#fff';
    g.font = Math.round(h*1.16) + 'px Consolas, "DejaVu Sans Mono", "Courier New", monospace';
    g.textAlign = 'center';
    g.textBaseline = 'middle';
    g.fillText(RAMP[i], w/2, h*0.515);
    const src = g.getImageData(0,0,w,h).data;
    const m = new Uint8Array(cellW*cellH);
    let any = 0;
    for (let y=0;y<cellH;y++) for (let x=0;x<cellW;x++){
      let acc = 0;
      for (let sy=0;sy<S;sy++) for (let sx=0;sx<S;sx++) acc += src[((((y*S+sy)*w)+(x*S+sx))<<2)+3];
      const v = (acc/(S*S))|0;
      m[y*cellW+x] = v;
      if (v) any++;
    }
    glyphs.push(any ? m : null);
  }
}

function resize(){
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const W = Math.max(320, Math.round(window.innerWidth  * dpr));
  const H = Math.max(240, Math.round(window.innerHeight * dpr));
  canvas.width = W; canvas.height = H;
  cellW = PRESETS[preset].cw;
  cellH = cellW*2;
  GW = Math.ceil(W/cellW); GH = Math.ceil(H/cellH);
  while (GW*GH > MAXCELLS && cellW < 40){
    cellW += 1; cellH = cellW*2;
    GW = Math.ceil(W/cellW); GH = Math.ceil(H/cellH);
  }
  NC = GW*GH;
  frame.width = GW*cellW; frame.height = GH*cellH;
  fctx.imageSmoothingEnabled = false;
  fdata = fctx.createImageData(frame.width, frame.height);
  f32 = new Uint32Array(fdata.data.buffer);
  colR = new Float32Array(NC); colG = new Float32Array(NC); colB = new Float32Array(NC);
  depth = new Float32Array(NC);
  gwx = new Float32Array(NC); gwz = new Float32Array(NC);
  rayX = new Float32Array(NC); rayY = new Float32Array(NC); rayZ = new Float32Array(NC);
  dith = new Float32Array(NC); vig = new Float32Array(NC); warm = new Float32Array(NC);
  const aspect = frame.width/frame.height;
  tanH = Math.tan(FOV_H*0.5);
  tanV = tanH/aspect;
  projX = (GW*0.5)/tanH; projY = (GH*0.5)/tanV;
  cxc = GW*0.5; cyc = GH*0.5;
  for (let j=0;j<GH;j++){
    const cdy = (1 - (j+0.5)/GH*2)*tanV;
    for (let i=0;i<GW;i++){
      const cdx = ((i+0.5)/GW*2 - 1)*tanH;
      const il = 1/Math.hypot(cdx,cdy,1);
      const o = j*GW+i;
      rayX[o] = cdx*il; rayY[o] = cdy*il; rayZ[o] = il;
      dith[o] = hash2(i*13+7, j*29+3);
      const nx = (i+0.5)/GW*2-1, ny = (j+0.5)/GH*2-1;
      vig[o] = 1 - 0.42*Math.pow(clamp(Math.hypot(nx*0.92,ny*0.98),0,1), 2.4);
      warm[o] = clamp(ny,0,1);
    }
  }
  buildGlyphs();
}

