/* ==========================================================================
   CAMERA + RENDER CORE
   ========================================================================== */
let camX=0, camY=0, camZ=0;
let F0=0,F1=0,F2=0, R0=1,R1=0,R2=0, U0=0,U1=1,U2=0;
const FOG_R = 0.150, FOG_G = 0.135, FOG_B = 0.225;
const FOG0 = 16, FOG1 = 86;
const ZEN_R = 0.026, ZEN_G = 0.033, ZEN_B = 0.078;
const HOR_R = 0.135, HOR_G = 0.108, HOR_B = 0.185;
const AMB_R = 0.100, AMB_G = 0.132, AMB_B = 0.225;
const MOON_LR = 1.00, MOON_LG = 0.965, MOON_LB = 0.885;
const MOON_COS = Math.cos(0.050);
// tangent frame on the moon disc
const MRl = (()=>{ const l = Math.hypot(MOONZ, MOONX) || 1; return [MOONZ/l, 0, -MOONX/l]; })();
const MUp = [ MRl[1]*MOONZ - MRl[2]*MOONY, MRl[2]*MOONX - MRl[0]*MOONZ, MRl[0]*MOONY - MRl[1]*MOONX ];

function shadeSky(o, dx, dy, dz){
  // base vertical gradient
  const up = clamp(dy,0,1);
  const g = Math.pow(up, 0.60);
  let r = lerp(HOR_R, ZEN_R, g), gg = lerp(HOR_G, ZEN_G, g), b = lerp(HOR_B, ZEN_B, g);
  const dot = dx*MOONX + dy*MOONY + dz*MOONZ;
  // warm haze around the moon
  const hz = Math.exp(-(1-dot)*6.5);
  r += 0.325*hz; gg += 0.185*hz; b += 0.115*hz;
  // blush band along the horizon
  const band = Math.exp(-Math.max(0,dy)*8.0);
  r += 0.085*band; gg += 0.022*band; b += 0.070*band;
  let dep = 1e9;
  // mountains
  let hl = Math.hypot(dx,dz);
  if (hl > 1e-5){
    const hx = dx/hl, hz2 = dz/hl;
    let az = Math.atan2(hz2, hx);          // [-pi,pi]
    const af = (az < 0 ? az + TAU : az)/TAU;
    const face = 0.45 + 0.55*Math.max(0, Math.cos(az - MOON_AZ));
    const c1 = crestAt(Crest1, af), c2 = crestAt(Crest2, af), c3 = crestAt(Crest3, af);
    const layered = (crest, base, haze, rim) => {
      if (dy >= crest) return false;
      const t = clamp((crest - dy)/0.055, 0, 1);
      let cr = base[0], cg = base[1], cb = base[2];
      cr = lerp(cr, FOG_R, haze); cg = lerp(cg, FOG_G, haze); cb = lerp(cb, FOG_B, haze);
      const snow = smoothstep(0.055, 0.16, crest) * smoothstep(0.25, 0.02, t) * 0.75;
      cr = lerp(cr, 0.80*MOON_LR, snow*facing); cg = lerp(cg, 0.80*MOON_LG, snow*facing); cb = lerp(cb, 0.88*MOON_LB, snow*facing);
      const rr2 = Math.exp(-t*7.0);
      r = lerp(cr, FOG_R, 0); gg = gg; // placeholder
      return true;
    };
    // far ridge
    if (dy < c1){
      const t = clamp((c1-dy)/0.055,0,1);
      let cr = lerp(0.098, FOG_R, 0.62), cg = lerp(0.096, FOG_G, 0.62), cb = lerp(0.168, FOG_B, 0.62);
      const snow = smoothstep(0.10,0.17,c1)*smoothstep(0.30,0.03,t)*0.85;
      cr = lerp(cr, 0.86*MOON_LR, snow*face); cg = lerp(cg, 0.86*MOON_LG, snow*face); cb = lerp(cb, 0.90*MOON_LB, snow*face);
      r = lerp(cr, r, smoothstep(0.72,1.0,t)*0.35);
      gg = lerp(cg, gg, smoothstep(0.72,1.0,t)*0.35);
      b  = lerp(cb, b,  smoothstep(0.72,1.0,t)*0.35);
      dep = 9000;
    }
    // mid ridge
    if (dy < c2){
      const t = clamp((c2-dy)/0.045,0,1);
      let cr = lerp(0.070, FOG_R, 0.38), cg = lerp(0.070, FOG_G, 0.38), cb = lerp(0.130, FOG_B, 0.38);
