/* ------------------------------ splatting -------------------------------- */
function splat(wx,wy,wz, cr,cg,cb, rad, alpha, fogAmt){
  const dx = wx-camX, dy = wy-camY, dz = wz-camZ;
  const zc = dx*F0 + dy*F1 + dz*F2;
  if (zc < 0.35) return;
  let f = fogAmt;
  if (f < 0) f = zc > FOG0 ? smoothstep(FOG0,FOG1,zc) : 0;
  if (f > 0.995) return;
  if (f > 0){
    cr = lerp(cr,FOG_R,f); cg = lerp(cg,FOG_G,f); cb = lerp(cb,FOG_B,f);
  }
  const inv = 1/zc;
  const sx = cxc + (dx*R0+dy*R1+dz*R2)*inv*projX;
  const sy = cyc - (dx*U0+dy*U1+dz*U2)*inv*projY;
