  const sx = cxc + (dx*R0+dy*R1+dz*R2)*inv*projX;
  const sy = cyc - (dx*U0+dy*U1+dz*U2)*inv*projY;
  let x0 = (sx-rad)|0, x1 = (sx+rad+1)|0, y0 = (sy-rad)|0, y1 = (sy+rad+1)|0;
  if (x1 < 0 || y1 < 0 || x0 >= GW || y0 >= GH) return;
  if (x0 < 0) x0 = 0; if (y0 < 0) y0 = 0;
  if (x1 > GW-1) x1 = GW-1; if (y1 > GH-1) y1 = GH-1;
