  const cs = Math.cos(skyRot), sn = Math.sin(skyRot);
  for (let i=0;i<stars.length;i++){
    const s = stars[i];
    const x = s.x*cs + s.z*sn, z = -s.x*sn + s.z*cs;
    const tw = 0.62 + 0.38*Math.sin(tm*s.sp + s.ph);
    const b = s.b*tw;
    if (b < 0.03) continue;
    splat(camX + x*20000, camY + s.y*20000, camZ + z*20000,
          s.r*b, s.g*b, s.bl*b, 0, 0.92, 0);
  }
}
function drawTrees(tm, px, pz){
  for (let ti=0; ti<trees.length; ti++){
    const tr = trees[ti];
    const cdx = tr.x-camX, cdy = (tr.y+5)-camY, cdz = tr.z-camZ;
    const zc = cdx*F0 + cdy*F1 + cdz*F2;
    if (zc < -4 || zc > FOG1+18) continue;
    const dist = Math.sqrt(cdx*cdx+cdy*cdy+cdz*cdz);
    if (dist > FOG1+15) continue;
    const rad = clamp(7.5/dist, 0.08, 2.5);
    const az = Math.atan2(tr.x, tr.z);
    const face = 0.72 + 0.38*Math.max(0, Math.cos(az - MOON_AZ));
    const swx = Math.sin(tm*0.62 + tr.phase)*0.16, swz = Math.cos(tm*0.47 + tr.phase*1.3)*0.13;
    const P = tr.pts;
    const h4 = dist < 26 ? 0.85 : 1;
    for (let i=0;i<P.length;i+=7){
      const w = P[i+6];
      const x = P[i] + swx*w, z = P[i+2] + swz*w;
      splat(x, P[i+1], z, P[i+3]*face, P[i+4]*face, P[i+5]*face, rad, 0.86);
    }
    if (dist < 46) glow(tr.x + swx, tr.y+5.4, tr.z + swz, 0.62, 0.30, 0.45, 3.6, 0.055);
  }
}
function drawStatics(){
  const CDX = 0;
  for (let i=0;i<statics.length;i+=6){
    const dx = statics[i]-camX, dy = statics[i+1]-camY, dz = statics[i+2]-camZ;
    const zc = dx*F0 + dy*F1 + dz*F2;
    if (zc < 0.35 || zc > FOG1+20) continue;
    const d = Math.sqrt(dx*dx+dy*dy+dz*dz);
    splat(statics[i],statics[i+1],statics[i+2], statics[i+3],statics[i+4],statics[i+5],
          clamp(6.5/d, 0.08, 1.6), 0.95);
  }
  for (let i=0;i<glows.length;i++){
    const g = glows[i];
    const d = Math.hypot(g.x-camX, g.y-camY, g.z-camZ);
