    p.ph += dt*(0.6 + p.sw);
    p.x += Math.sin(p.ph)*p.sw*dt*1.6 + dt*1.15;             // lazy drift
    p.z += Math.cos(p.ph*0.7)*p.sw*dt*0.9 + dt*0.5;
    const gy = hAt(p.x,p.z);
    if (p.y < gy - 0.05 || Math.abs(p.x-playerX) > 40 || Math.abs(p.z-playerZ) > 40){
      petals[i] = newPetal(false);
      continue;
    }
    const vm = 0.55 + 0.45*Math.sin(p.ph*1.4);
    const cr = lerp(0.80,1.00,p.tone)*vm, cg = lerp(0.44,0.62,p.tone)*vm, cb = lerp(0.56,0.74,p.tone)*vm;
    splat(p.x, p.y, p.z, cr, cg, cb, p.size, 0.9);
  }
}
function drawFlies(tm, dt){
  for (let i=0;i<flies.length;i++){
    const f = flies[i];
    f.ph += dt*f.sp;
    f.b = 0.35 + 0.65*Math.pow(Math.max(0, Math.sin(f.ph)), 2.2);
    if (f.b < 0.05) continue;
    const x = f.x + Math.sin(f.ph*0.8)*f.r, z = f.z + Math.cos(f.ph*0.63)*f.r;
    const y = f.y + Math.sin(f.ph*1.7)*0.45;
    glow(x,y,z, 0.95*f.b, 1.0*f.b, 0.55*f.b, 1.5, 0.42);
  }
}
function drawWanderer(tm){
  const mv = moveAmt;
  const bob = Math.sin(walkPhase*2)*0.05*mv;
  const swing = Math.sin(walkPhase)*0.52*mv;
  const dist = Math.hypot(playerX-camX, playerY+1-camY, playerZ-camZ);
  const rad = clamp(3.4/dist, 0.2, 1.5);
  const cs = Math.cos(facing), sn = Math.sin(facing);
  const light = 0.62 + 0.55*Math.max(0, Math.cos(facing - MOON_AZ)) + 0.30;   // moon + lantern
  const part = (pts, swingA, pvY, pvZ) => {
    const ss = Math.sin(swingA), sc = Math.cos(swingA);
    for (let i=0;i<pts.length;i+=6){
      let x = pts[i], y = pts[i+1]-pvY, z = pts[i+2]-pvZ;
      const y2 = y*sc - z*ss, z2 = y*ss + z*sc;
      y = y2+pvY; z = z2+pvZ;
      const wx = playerX + (x*cs + z*sn);
      const wz = playerZ + (-x*sn + z*cs);
      splat(wx, playerY + y + bob, wz,
            pts[i+3]*light, pts[i+4]*light, pts[i+5]*light, rad, 0.94);
    }
  };
  part(CHAR.torso, 0, 0, 0);
  part(CHAR.head, 0, 0, 0);
  part(CHAR.hair, 0, 0, 0);
  part(CHAR.legL, swing, 0.86, 0);
  part(CHAR.legR, -swing, 0.86, 0);
  part(CHAR.armL, -swing*0.7, 1.26, 0);
  part(CHAR.armR, swing*0.7, 1.26, 0);
