  const ls = Math.sin(-swing*0.7), lc = Math.cos(-swing*0.7);
  let lx = CHAR.lamp.x, ly = CHAR.lamp.y-1.26, lz = CHAR.lamp.z;
  const ly2 = ly*lc - lz*ls, lz2 = ly*ls + lz*lc;
  ly = ly2+1.26; lz = lz2;
  const wx = playerX + (lx*cs + lz*sn), wz = playerZ + (-lx*sn + lz*cs);
  const flame = 0.85 + 0.15*Math.sin(tm*3.1);
  glow(wx, playerY+ly+bob, wz, 1.0*flame, 0.70*flame, 0.34*flame, 3.2, 0.34);
}
function drawShadow(){
  const sx = playerX - MOONX*0.42, sz = playerZ - MOONZ*0.42;
  for (let o=0;o<NC;o++){
    if (depth[o] > 1e8) continue;
    const dx = gwx[o]-sx, dz = gwz[o]-sz;
    const d2 = dx*dx+dz*dz;
    if (d2 > 1.5) continue;
    const f = 1 - 0.62*(1 - smoothstep(0.22, 1.15, Math.sqrt(d2)));
    colR[o]*=f; colG[o]*=f; colB[o]*=f;
  }
