/* ------------------------------ ASCII blit ------------------------------- */
let outBuf32 = null;
function blit(){
  const CW = cellW, CH = cellH, FW = frame.width;
  const nR = RAMP.length-1;
  let p = 0;
  for (let j=0;j<GH;j++){
    for (let i=0;i<GW;i++,p++){
      let r = colR[p]*vig[p], g = colG[p]*vig[p], b = colB[p]*vig[p];
      const lum = 0.299*r + 0.587*g + 0.114*b;
      const l2 = Math.sqrt(clamp(lum,0,1.6)) * 0.92;
      let idx = (l2*n + (dith[p]-0.5)*0.95)|0;
      if (idx < 0) idx = 0; else if (idx > nR) idx = nR;
      const m = glyphs[idx];
      const x0 = i*CW, y0 = j*CH;
      if (!m){
        // blank cell — wash the background with a whisper of its color
        const w = 0xff000000 | ((b*0.085*255)|0)<<16 | ((g*0.085*255)|0)<<8 | ((r*0.085*255)|0);
        for (let y=0;y<CH;y++){
          let q = (y0+y)*FW + x0;
          for (let x=0;x<CW;x++) outBuf32[q++] = w;
        }
        continue;
      }
      const bgk = 0.075 + 0.42*Math.max(0, lum-0.52);
      const br = r*bgk, bgg = g*bgk, bb = b*bgk;
      for (let y=0;y<CH;y++){
        let q = (y0+y)*FW + x0;
        const mrow = y*CW;
        for (let x=0;x<CW;x++,q++){
          const a = m[mrow+x];
          if (!a){ outBuf32[q] = 0xff000000 | ((bb*255)|0)<<16 | ((bgg*255)|0)<<8 | ((br*255)|0); continue; }
          const ia = 255-a;
          const rr3 = (br + (r - br)*a*0.00390625);
          const gg3 = (bgg + (g - bgg)*a*0.00390625);
          const bb3 = (bb + (b - bb)*a*0.00390625);
          outBuf32[q] = 0xff000000 | ((bb3>1?1:bb3)*255|0)<<16 | ((gg3>1?1:gg3)*255|0)<<8 | ((rr3>1?1:rr3)*255|0);
        }
      }
    }
  }
  fctx.putImageData(fdata,0,0);
  const cw = canvas.width, ch = canvas.height;
  const sc = Math.min(cw/frame.width, ch/frame.height);
  const dw = frame.width*sc, dh = frame.height*sc;
  ctx.imageSmoothingEnabled = false;
  ctx.fillStyle = '#03040a';
  ctx.fillRect(0,0,cw,ch);
  ctx.drawImage(frame, (cw-dw)*0.5, (ch-dh)*0.5, dw, dh);
}

