/* ==========================================================================
   FRAME
   ========================================================================== */
function render(tm, dt){
  const Y = camYaw, P = camPitch;
  const sY = Math.sin(Y), cY = Math.cos(Y), sP = Math.sin(P), cP = Math.cos(P);
  F0 = -sY*cP; F1 = -sP; F2 = -cY*cP;
  R0 =  cY;    R1 =  0;  R2 = -sY;
  U0 = -sY*sP; U1 =  cP; U2 = -cY*sP;

  // --- sky & landscape -----------------------------------------------------
  for (let o=0;o<NC;o++){
    const cdx = rayX[o], cdy = rayY[o], cdz = rayZ[o];
    const dx = R0*cdx + U0*cdy + F0*cdz;
    const dy = R1*cdx + U1*cdy + F1*cdz;
    const dz = R2*cdx + U2*cdy + F2*cdz;
    if (dy < -0.005) shadeGround(o, camX, camY, camZ, dx, dy, dz, tm);
    else             shadeSky(o, dx, dy, dz);
  }
  // --- everything that lives in the glade ----------------------------------
  drawStars(tm);
  drawTrees(tm, playerX, playerZ);
  drawStatics();
  drawFlies(tm, dt);
  drawPetals(dt, tm);
  drawWanderer(tm);
  drawShadow();
  blit();
}

/* ==========================================================================
   THE WALKER
   ========================================================================== */
const keys = Object.create(null);
let camYaw = 2.32, camPitch = 0.125, camDist = 6.4;
let facing = -0.82, walkPhase = 0, moveAmt = 0, idleT = 0, lookIdle = 0;
let bobT = 0;
const camTX = [], camTY = [], camTZ = [];
function angLerp(a,b,t){
  let d = (b - a) % TAU;
  if (d >  Math.PI) d -= TAU;
  if (d < -Math.PI) d += TAU;
  return a + d*t;
}
function tryMove(nx, nz){
  const h = hAt(nx, nz);
  if (h < WATER - 0.30) return false;
  if (Math.hypot(nx,nz) > 104) return false;
  return true;
}
function update(dt, tm){
  // ---- look -------------------------------------------------------------
  if (keys['q']) { camYaw += dt*1.5; idleT = 0; }
  if (keys['e']) { camYaw -= dt*1.5; idleT = 0; }
  if (keys['r']) { camPitch = clamp(camPitch - dt*0.9, -0.30, 0.72); idleT = 0; }
  if (keys['f']) { camPitch = clamp(camPitch + dt*0.9, -0.30, 0.72); idleT = 0; }

  // ---- walk -------------------------------------------------------------
  let ix = 0, iz = 0;
  if (keys['w'] || keys['arrowup'])    iz += 1;
  if (keys['s'] || keys['arrowdown'])  iz -= 1;
  if (keys['d'] || keys['arrowright']) ix += 1;
  if (keys['a'] || keys['arrowleft'])  ix -= 1;
  const run = !!(keys['shift']);
  const fy = -Math.sin(camYaw), fz = -Math.cos(camYaw);
  const ry =  Math.cos(camYaw), rz = -Math.sin(camYaw);
  let dx = fy*iz + ry*ix, dz = fz*iz + rz*ix;
  const dl = Math.hypot(dx,dz);
  if (dl > 1e-4){
    dx /= dl; dz /= dl;
    const spd = run ? 8.6 : 3.15;
    const step = spd*dt;
    let nx = playerX + dx*step, nz = playerZ + dz*step;
    if (tryMove(nx,nz)){ playerX = nx; playerZ = nz; }
    else if (tryMove(playerX + dx*step, playerZ)) playerX += dx*step;      // slide
    else if (tryMove(playerX, playerZ + dz*step)) playerZ += dz*step;
    facing = angLerp(facing, Math.atan2(dx,dz), 1 - Math.exp(-dt*10));
    moveAmt += (1 - moveAmt)*(1 - Math.exp(-dt*6));
    walkPhase += dt*spd*2.0*(run?0.92:1.0);
    idleT = 0; lookIdle = 0;
  } else {
    moveAmt += (0 - moveAmt)*(1 - Math.exp(-dt*5));
    walkPhase += dt*0.6*moveAmt;
    idleT += dt;
    // after a long pause the camera drifts on its own — very slow, very calm
    if (idleT > 5){
      lookIdle = Math.min(1, lookIdle + dt*0.35);
      camYaw += dt*0.035*lookIdle;
    }
  }
  gameT = tm;
  playerY += (hAt(playerX, playerZ) - playerY)*(1 - Math.exp(-dt*11));
  bobT += dt;

  // ---- third person rig -------------------------------------------------
  const tx = playerX, ty = playerY + 1.38, tz = playerZ;
  const ox = Math.sin(camYaw)*Math.cos(camPitch),
        oy = Math.sin(camPitch),
        oz = Math.cos(camYaw)*Math.cos(camPitch);
  let d = camDist;
  for (let k=0;k<10;k++){
    const px = tx + ox*d, py = ty + oy*d, pz = tz + oz*d;
    if (py > hAt(px,pz) + 0.95) break;
    d -= camDist/10;
    if (d < 1.8){ d = 1.8; break; }
  }
  let px = tx + ox*d, py = ty + oy*d, pz = tz + oz*d;
  const hh = hAt(px,pz) + 0.85;
  if (py < hh) py = hh;
  // gentle spring so the walk feels unhurried
  if (!camInit){ camX = px; camY = py; camZ = pz; camInit = true; }
  const k2 = 1 - Math.exp(-dt*9);
  camX += (px - camX)*k2;
  camY += (py - camY)*k2;
  camZ += (pz - camZ)*k2;
}
let camInit = false, gameT = 0;

//__NEXT__

