/* ==========================================================================
   SOUND — a slow, breathy night ambience
   ========================================================================== */
let AC = null, master = null, muted = false, pluckTimer = null;
const PENTA = [146.83,164.81,196.00,220.00,246.94,293.66,329.63,392.00,440.00,493.88,587.33,659.25];
function initAudio(){
  if (AC) return;
  const Ctx = window.AudioContext || window.webkitAudioContext;
  if (!Ctx) return;
  try { AC = new Ctx(); } catch(e){ return; }
  master = AC.createGain();
  master.gain.value = 0.0001;
  master.connect(AC.destination);
  master.gain.linearRampToValueAtTime(muted ? 0.0001 : 0.55, AC.currentTime + 5);

  // ---- simple feedback reverb ----
  const dl1 = AC.createDelay(1.0); dl1.delayTime.value = 0.37;
  const dl2 = AC.createDelay(1.0); dl2.delayTime.value = 0.61;
  const damp = AC.createBiquadFilter(); damp.type = 'lowpass'; damp.frequency.value = 2100;
  const fb = AC.createGain(); fb.gain.value = 0.44;
  dl1.connect(damp); dl2.connect(damp);
  damp.connect(fb); fb.connect(dl1); fb.connect(dl2);
  const verbOut = AC.createGain(); verbOut.gain.value = 0.42;
  damp.connect(verbOut); verbOut.connect(master);
  const send = AC.createGain(); send.gain.value = 1;
  send.connect(dl1); send.connect(dl2);
  function pluck(f, when, dur, amp){
    const o = AC.createOscillator(); o.type = 'triangle'; o.frequency.value = f;
    const o2 = AC.createOscillator(); o2.type = 'sine'; o2.frequency.value = f*2.005;
    const g = AC.createGain(), g2 = AC.createGain();
    g.gain.setValueAtTime(0.0001, when);
    g.gain.exponentialRampToValueAtTime(amp, when + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, when + dur);
    g2.gain.setValueAtTime(0.0001, when);
    g2.gain.exponentialRampToValueAtTime(amp*0.22, when + 0.02);
    g2.gain.exponentialRampToValueAtTime(0.0001, when + dur*0.3);
    o.connect(g); o2.connect(g2);
    g.connect(master); g.connect(send); g2.connect(send);
    o.start(when); o2.start(when);
    o.stop(when + dur + 0.1); o2.stop(when + dur*0.4);
  }
  // ---- pad ----
  const padGain = AC.createGain(); padGain.gain.value = 0.075;
  padGain.connect(master); padGain.connect(send);
  [73.42,110.00,146.83,220.00,293.66].forEach((f,i)=>{
    const o = AC.createOscillator();
    o.type = i % 2 ? 'triangle' : 'sine';
    o.frequency.value = f*(i%2 ? 1.0016 : 1.0);
    const g = AC.createGain(); g.gain.value = 0.55/(i+1);
    o.connect(g); g.connect(padGain);
    const lfo = AC.createOscillator(); lfo.frequency.value = 0.021 + i*0.013;
    const lg = AC.createGain(); lg.gain.value = 3.2;
    lfo.connect(lg); lg.connect(o.detune);
    o.start(); lfo.start();
  });
  // ---- wind ----
  const len = AC.sampleRate*4;
  const buf = AC.createBuffer(1, len, AC.sampleRate);
  const ch = buf.getChannelData(0);
  let lw = 0;
  for (let i=0;i<len;i++){ const w = Math.random()*2-1; lw = lw*0.985 + w*0.015; ch[i] = lw*3.0; }
  const src = AC.createBufferSource(); src.buffer = buf; src.loop = true;
  const bp = AC.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 420; bp.Q.value = 0.8;
  const wg = AC.createGain(); wg.gain.value = 0.055;
  const wl = AC.createOscillator(); wl.frequency.value = 0.032;
  const wlg = AC.createGain(); wlg.gain.value = 190;
  wl.connect(wlg); wlg.connect(bp.frequency);
  src.connect(bp); bp.connect(wg); wg.connect(master); wg.connect(send);
  src.start(); wl.start();
  // ---- drifting chimes ----
  const chime = () => {
    if (!AC) return;
    if (!muted && AC.state === 'running'){
      const n = 1 + (Math.random() < 0.34 ? 1 : 0);
      for (let i=0;i<n;i++){
        const f = PENTA[(Math.random()*PENTA.length)|0];
        pluck(f, AC.currentTime + i*0.42, 3.6 + Math.random()*3.4, 0.045 + Math.random()*0.05);
      }
    }
    pluckTimer = setTimeout(chime, 2600 + Math.random()*6200);
  };
  chime();
}
function toggleMute(){
  muted = !muted;
  if (master && AC){
    master.gain.cancelScheduledValues(AC.currentTime);
    master.gain.setValueAtTime(master.gain.value, AC.currentTime);
    master.gain.linearRampToValueAtTime(muted ? 0.0001 : 0.55, AC.currentTime + 1.2);
  }
}

/* ==========================================================================
   INPUT / HUD / LOOP
   ========================================================================== */
const hud = document.getElementById('hud');
const hint = document.getElementById('hint');
const startEl = document.getElementById('start');
const titleEl = document.getElementById('title');
let hudOn = true, started = false;
let presetCap = 2;
let flashMsg = '', flashT = 0;

function flash(m){ flashMsg = m; flashT = 3; }
function updateHud(){
  if (!hudOn){ hud.style.display = 'none'; return; }
  hud.style.display = 'block';
  hud.innerHTML =
    'fps <b>' + fps.toFixed(0) + '</b><br>' +
    'grid <b>' + GW + '×' + GH + '</b><br>' +
    'chars <b>' + (NC/1000).toFixed(1) + 'k</b><br>' +
    'quality <b>' + PRESETS[preset].name + '</b>' +
    (flashT > 0 ? '<br><b>' + flashMsg + '</b>' : '');
}
function begin(){
  if (started) return;
  started = true;
  initAudio();
  if (AC && AC.state === 'suspended') AC.resume();
  startEl.style.opacity = '0';
  setTimeout(()=>{ startEl.style.display = 'none'; }, 950);
  titleEl.style.opacity = '1';
  setTimeout(()=>{ titleEl.style.opacity = '0'; }, 9000);
  if (canvas.requestPointerLock) canvas.requestPointerLock();
}
startEl.addEventListener('click', begin);
window.addEventListener('keydown', e=>{
  if (!started && (e.key === ' ' || e.key === 'Enter')){ begin(); return; }
  const k = e.key.length === 1 ? e.key.toLowerCase() : e.key.toLowerCase();
  if (k === 'shift') keys['shift'] = true; else keys[k] = true;
  if (['arrowup','arrowdown','arrowleft','arrowright',' '].indexOf(k) >= 0) e.preventDefault();
  if (k === 'm') toggleMute();
  if (k === 'h'){ hudOn = !hudOn; updateHud(); }
  if (k === '1' || k === '2' || k === '3'){
    preset = +k - 1; presetCap = preset; resize(); camInit = false;
    flash('quality → ' + PRESETS[preset].name);
  }
});
window.addEventListener('keyup', e=>{
  const k = e.key.toLowerCase();
  if (k === 'shift') keys['shift'] = false; else keys[k] = false;
});
window.addEventListener('blur', ()=>{ for (const k in keys) keys[k] = false; });
canvas.addEventListener('click', ()=>{ if (started && canvas.requestPointerLock) canvas.requestPointerLock(); });
document.addEventListener('mousemove', e=>{
  if (!started) return;
  const locked = document.pointerLockElement === canvas;
  if (!locked && !dragging) return;
  camYaw   -= e.movementX*0.0024;
  camPitch  = clamp(camPitch + e.movementY*0.0017, -0.30, 0.72);
  idleT = 0; lookIdle = 0;
});
let dragging = false, lastMX = 0, lastMY = 0;
canvas.addEventListener('mousedown', e=>{ dragging = true; });
window.addEventListener('mouseup', ()=>{ dragging = false; });
canvas.addEventListener('wheel', e=>{
  e.preventDefault();
  camDist = clamp(camDist + e.deltaY*0.0032, 2.2, 15);
}, { passive:false });
window.addEventListener('resize', ()=>{ resize(); camInit = false; });
document.addEventListener('visibilitychange', ()=>{ last = performance.now(); });

let fps = 60, fAcc = 0, fCnt = 0, slowN = 0, fastN = 0, last = performance.now(), T = 0;
function autoQuality(){
  if (fps < 27) slowN++; else slowN = Math.max(0, slowN - 1);
  if (fps > 56) fastN++; else fastN = 0;
  if (slowN > 4 && preset > 0){
    preset--; slowN = 0; presetCap = preset; resize(); camInit = false;
    flash('auto · quality → ' + PRESETS[preset].name);
  } else if (fastN > 24 && preset < presetCap){
    preset++; fastN = 0; resize(); camInit = false;
  }
}
function loop(now){
  requestAnimationFrame(loop);
  const dt = Math.min(0.06, (now - last)/1000);
  last = now; T += dt;
  if (flashT > 0) flashT -= dt;
  update(dt, T);
  render(T, dt);
  fAcc += dt; fCnt++;
  if (fAcc > 0.5){
    fps = fCnt/fAcc; fAcc = 0; fCnt = 0;
    updateHud();
    autoQuality();
  }
}

/* ==========================================================================
   BOOT
   ========================================================================== */
