function shadeGround(o, ox,oy,oz, dx,dy,dz, tm){
  let t = 0.55, hit = -1, px=0,py=0,pz=0;
  for (let s=0;s<18;s++){
    const dt = t < 6 ? 1.15 : (t < 26 ? t*0.30 : t*0.52);
    const nt = t + dt;
    if (nt > 96) break;
    px = ox+dx*nt; py = oy+dy*nt; pz = oz+dz*nt;
    if (py <= hAt(px,pz)){
      let a = t, b = nt;
      for (let k=0;k<8;k++){
        const m = (a+b)*0.5, mx = ox+dx*m, my = oy+dy*m, mz = oz+dz*m;
        if (my - hAt(mx,mz) > 0) a = m; else b = m;
      }
      hit = b; break;
    }
    t = nt;
  }
  if (hit < 0){                        // lost in the mist �?" paint pure haze
    colR[o]=FOG_R; colG[o]=FOG_G; colB[o]=FOG_B; depth[o]=1e8; gwx[o]=0; gwz[o]=0;
    return;
  }
  px = ox+dx*hit; py = oy+dy*hit; pz = oz+dz*hit;
  const hh = hAt(px,pz);
  const fog = smoothstep(FOG0, FOG1, hit);
  let r,g,b;
  if (hh < WATER && dy < -1e-4){
    const tw = (WATER - oy)/dy;
    if (tw > 0 && tw < hit){
      px = ox+dx*tw; pz = oz+dz*tw; py = WATER; hit = tw;
    }
    const fres = 0.08 + 0.70*Math.pow(1-clamp(Math.abs(dy),0,1), 2.4);
    r = lerp(0.020, HOR_R*1.22, fres);
    g = lerp(0.036, HOR_G*1.25, fres);
    b = lerp(0.082, HOR_B*1.30, fres);
    // moon glitter path
    const rfx = dx, rfy = -dy, rfz = dz;
    const sd = rfx*MOONX + rfy*MOONY + rfz*MOONZ;
    if (sd > 0.80){
      const wav = 0.5 + 0.5*Math.sin(px*1.15 + tm*1.35)*Math.sin(pz*1.31 - tm*1.15) + 0.35*Math.sin(px*3.7 - tm*2.1)*Math.sin(pz*4.3 + tm*1.7);
      const shim = clamp(wav,0,1);
      const sharp = Math.pow(sd, 300)*3.1;
      const broad = Math.pow(sd, 11)*0.30*(0.35 + 0.85*shim);
      const gl = sharp + broad;
      r += MOON_LR*gl; g += MOON_LG*gl*0.96; b += MOON_LB*gl*0.92;
    }
    r += 0.035; g += 0.018; b += 0.030;                 // blossom blush on the water
    depth[o] = hit; gwx[o]=px; gwz[o]=pz;
  } else {
    const nx = bilin(Ng,px,pz,3,0), ny = bilin(Ng,px,pz,3,1), nz = bilin(Ng,px,pz,3,2);
    const ar = bilin(Cg,px,pz,3,0), ag = bilin(Cg,px,pz,3,1), ab = bilin(Cg,px,pz,3,2);
    const nd = Math.max(0, nx*MOONX + ny*MOONY + nz*MOONZ);
    const diff = nd*nd;
