function fastAz(y,x){
  const ay = (y < 0 ? -y : y) + 1e-10;
  let r, a;
  if (x >= 0){ r = (x - ay)/(x + ay); a = AT_C1*r*r + AT_C2*r + AT_Q; }
  else       { r = (x + ay)/(ay - x); a = AT_C1*r*r + AT_C2*r + AT_T; }
  return y < 0 ? -a : a;
}

