const http = require('http'), fs = require('fs'), path = require('path');
const root = 'D:/proj';
const types = {'.html':'text/html','.js':'text/javascript','.css':'text/css','.png':'image/png'};
http.createServer((req,res)=>{
  if (req.method === 'POST' && req.url.split('?')[0] === '/__save'){
    let body = '';
    req.on('data', c => { body += c; });
    req.on('end', () => {
      try {
        const m = /^data:image\/png;base64,(.*)$/.exec(body);
        const b64 = m ? m[1] : body;
        const out = path.join(root, '__shot.png');
        fs.writeFileSync(out, Buffer.from(b64, 'base64'));
        res.writeHead(200, {'Content-Type':'text/plain'});
        res.end('saved ' + out);
      } catch(e){ res.writeHead(500); res.end(String(e)); }
    });
    return;
  }
  let p = decodeURIComponent(req.url.split('?')[0]);
  if (p === '/') p = '/moonlit-grove.html';
  const f = path.join(root, p);
  fs.readFile(f, (e,d)=>{
    if (e){ res.writeHead(404); res.end('no'); return; }
    res.writeHead(200, {'Content-Type': types[path.extname(f)] || 'application/octet-stream'});
    res.end(d);
  });
}).listen(8765, ()=>console.log('serving D:/proj on 8765'));

